# EXACT proof that (P - Q) * m_d lies in the Jacobian ideal of G_x for generic x  (AI-written, unreviewed).
#   G_x = h0(y) + h0(p) + h0(q) + M_x,  M_x = sum_{i,j} x_(i-j) y_(i+j) p_i q_j,  m_d = dM_x/dx_d,
#   P = p_0 p_1 p_2,  Q = q_0 q_1 q_2.
# Method (no Groebner basis, no function field):
#  1. Columns: products mu * dG/dv (v a variable, mu a quartic monomial) of the same torus weight as the target;
#     each is a vector with entries of degree <= 1 in x = (x_0, x_1, x_2).  Target t = (P - Q) m_d: constant vector.
#     The columns are symmetrised over the group of order 6 generated by sh' and iota' (permutations of the
#     variables that preserve G_x for every x; t is invariant under sh' and changes sign under iota'), with the
#     matching signs.  A symmetrised column is still an element of the Jacobian ideal, so nothing is assumed here.
#  2. MOD p, at random x: thin the columns to a small set S (s columns) that still contains t in its span.
#  3. EXACT, integers: at every grid point x >= 0 with x_0 + x_1 + x_2 <= s the integer matrix [N_S(x) | t] has
#     rank <= s.  Every (s+1)-minor of [N_S | t] is a polynomial of total degree <= s in x (only the s columns of
#     N_S depend on x, linearly), and a polynomial of total degree <= s that vanishes at all these points is zero.
#     So every (s+1)-minor vanishes identically.  If moreover N_S(x) has rank s at one point, then for generic x
#     t is a combination of the columns of N_S(x), i.e. t is in the Jacobian ideal of G_x.
# usage: python3 t_ks_grid.py [d ...]
import sys, random, itertools, time
from collections import defaultdict
from flint import fmpz_mat, nmod_mat
NVV = 9          # y0 y1 y2 p0 p1 p2 q0 q1 q2
def ch(e):
    y = e[0:3]; p = e[3:6]; q = e[6:9]
    return ((y[1] + 2 * y[2] - p[1] - 2 * p[2] - q[1] - 2 * q[2]) % 3, (sum(p) - sum(q)) % 3, (sum(y) - sum(p)) % 3)
def mons(deg, n=NVV):
    out = []
    def rec(i, left, cur):
        if i == n - 1: out.append(tuple(cur + [left])); return
        for a in range(left + 1): rec(i + 1, left - a, cur + [a])
    rec(0, deg, []); return out
def unit(i):
    e = [0] * NVV; e[i] = 1; return tuple(e)
def add(a, b): return tuple(x + y for x, y in zip(a, b))
def polyG():
    G = defaultdict(int)                         # (index of x-variable or -1, monomial) -> coefficient
    for i in range(NVV):
        e = [0] * NVV; e[i] = 3; G[(-1, tuple(e))] += 1
    for i in range(3):
        for j in range(3):
            e = [0] * NVV; e[(i + j) % 3] += 1; e[3 + i] += 1; e[6 + j] += 1
            G[((i - j) % 3, tuple(e))] += 1
    return G
def dpoly(G, v):
    out = defaultdict(int)
    for (xm, e), c in G.items():
        if e[v]:
            e2 = list(e); e2[v] -= 1; out[(xm, tuple(e2))] += c * e[v]
    return out
G = polyG(); dG = [dpoly(G, v) for v in range(NVV)]
# sanity: the torus weight of dG/dv is minus that of v
for v in range(NVV):
    assert len({ch(e) for (_, e) in dG[v]}) == 1 and all(ch(add(e, unit(v))) == (0, 0, 0) for (_, e) in dG[v])
def target(d, kind="P-Q"):
    T = defaultdict(int)
    for i in range(3):
        j = (i - d) % 3
        m = [0] * NVV; m[(i + j) % 3] += 1; m[3 + i] += 1; m[6 + j] += 1
        A = list(m); B = list(m)
        if kind == "P-Q":
            for t in range(3): A[3 + t] += 1; B[6 + t] += 1
            T[tuple(A)] += 1; T[tuple(B)] -= 1
        elif kind == "P+Q":
            for t in range(3): A[3 + t] += 1; B[6 + t] += 1
            T[tuple(A)] += 1; T[tuple(B)] += 1
    return T
quart = mons(4)
# the two permutations: sh': y_k -> y_(k+2), p_i -> p_(i+1), q_i -> q_(i+1);  iota': y_k -> y_(-k), p_i <-> q_(-i)
SH = [0] * NVV; IO = [0] * NVV
for k in range(3):
    SH[k] = (k + 2) % 3; SH[3 + k] = 3 + (k + 1) % 3; SH[6 + k] = 6 + (k + 1) % 3
    IO[k] = (-k) % 3; IO[3 + k] = 6 + (-k) % 3; IO[6 + k] = 3 + (-k) % 3
def pm(perm, e):
    out = [0] * NVV
    for i in range(NVV): out[perm[i]] += e[i]
    return tuple(out)
for perm in (SH, IO):      # they preserve G_x for every x (labels of the x-variables included)
    assert {(xm, pm(perm, e)): c for (xm, e), c in G.items()} == dict(G)
GROUP = []                 # (permutation, sign): sh'^a iota'^b with sign (-1)^b
for a in range(3):
    for b in range(2):
        perm = list(range(NVV))
        for _ in range(b): perm = [IO[i] for i in perm]
        for _ in range(a): perm = [SH[i] for i in perm]
        GROUP.append((perm, -1 if b else 1))
def column(v, mu):
    """sum over the group of sign(g) * g(mu) * dG/d(g v): an element of the Jacobian ideal, linear in x"""
    out = defaultdict(int)
    for perm, sg in GROUP:
        v2 = perm[v]; mu2 = pm(perm, mu)
        for (xm, e), c in dG[v2].items(): out[(xm, add(mu2, e))] += sg * c
    return {k: c for k, c in out.items() if c}
_seen = set(); COLS = []
for v in range(NVV):
    for mu in quart:
        if ch(mu) != ch(unit(v)): continue
        orb = frozenset((perm[v], pm(perm, mu)) for perm, sg in GROUP)
        if orb in _seen: continue
        _seen.add(orb)
        if column(v, mu): COLS.append((v, mu))
def build(colset, T):
    """rows = sextic monomials; returns row index and, per column, list of (row, xm, coef)"""
    rows = {}
    def rid(e):
        if e not in rows: rows[e] = len(rows)
        return rows[e]
    cols = []
    for (v, mu) in colset:
        cols.append([(rid(e), xm, c) for (xm, e), c in column(v, mu).items()])
    tv = [(rid(e), c) for e, c in T.items()]
    return rows, cols, tv
def eval_mat(rows, cols, tv, x, with_t=True):
    nr = len(rows); nc = len(cols) + (1 if with_t else 0)
    M = [[0] * nc for _ in range(nr)]
    for j, col in enumerate(cols):
        for r, xm, c in col: M[r][j] += c * (1 if xm < 0 else x[xm])
    if with_t:
        for r, c in tv: M[r][nc - 1] += c
    return M
def rank_mod(M, p):
    return nmod_mat([[a % p for a in row] for row in M], p).rank()
def thin(T, p=2147483629, seed=1):
    rnd = random.Random(seed)
    pts = [[rnd.randrange(1, p) for _ in range(3)] for _ in range(2)]
    def inspan(colset):
        rows, cols, tv = build(colset, T)
        for x in pts:
            if rank_mod(eval_mat(rows, cols, tv, x), p) != rank_mod(eval_mat(rows, cols, tv, x, with_t=False), p): return False
        return True
    S = list(COLS)
    if not inspan(S): return None
    # first: an independent subset (pivot columns at the first point), then greedy removal
    rnd.shuffle(S)
    changed = True
    while changed:
        changed = False
        for blk in (32, 8, 2, 1):
            i = 0
            while i < len(S):
                trial = S[:i] + S[i + blk:]
                if trial and inspan(trial): S = trial; changed = True
                else: i += blk
    return S
if __name__ == "__main__":
    ds = [int(a) for a in sys.argv[1:]] or [0, 1, 2]
    print("symmetrised columns of the right torus weight: %d (from %d products mu * dG/dv)" % (len(COLS), NVV * len(quart)))
    for d in ds:
        t0 = time.time()
        Tc = target(d, "P+Q")
        print("d = %d: control, MOD p: (P + Q) m_d in the span of all columns at random x: %s" % (d, thin(Tc) is not None), flush=True)
        T = target(d)
        S = thin(T)
        if S is None: print("d = %d: (P - Q) m_d is NOT in the span MOD p at random x; stop" % d); continue
        s = len(S)
        rows, cols, tv = build(S, T)
        print("d = %d: thinned to s = %d columns, %d rows   [%.0fs]" % (d, s, len(rows), time.time() - t0), flush=True)
        bad = 0; full = 0; npts = 0
        for x in itertools.product(range(s + 1), repeat=3):
            if sum(x) > s: continue
            M = fmpz_mat(eval_mat(rows, cols, tv, x))
            r = M.rank(); npts += 1
            if r > s: bad += 1
            if full == 0:
                if fmpz_mat(eval_mat(rows, cols, tv, x, with_t=False)).rank() == s: full = 1; xfull = x
        print("d = %d: EXACT: grid {x >= 0, |x| <= %d}: %d points; points where rank [N_S | t] > s: %d; a point where rank N_S = s: %s   [%.0fs]"
              % (d, s, npts, bad, xfull if full else None, time.time() - t0), flush=True)
        print("RESULT d = %d: (P - Q) m_d in the Jacobian ideal of G_x for generic x: %s (EXACT)" % (d, "PROVED" if bad == 0 and full else "NOT PROVED"), flush=True)
